import { MakeLogicType, actions, kea, path, reducers, selectors } from 'kea'
import { loaders } from 'kea-loaders'

import api from 'lib/api'
import { isDefinitionStale } from 'lib/utils/definitions'

import { EventDefinition } from '~/types'

/** Why an action step matches nothing, or is about to. */
export type EventHealthIssue = { status: 'stale'; lastSeenAt: string } | { status: 'missing' }

/** Definitions found, keyed by event name. A name that resolved to nothing maps to `null`. */
export type EventDefinitionsByName = Record<string, EventDefinition | null>

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface actionEventHealthLogicValues {
    definitions: EventDefinitionsByName
    definitionsLoading: boolean
    eventHealthIssues: Record<string, EventHealthIssue>
    requestedNames: string[]
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface actionEventHealthLogicActions {
    requestEventNames: (names: (string | null | undefined)[]) => {
        names: (string | null | undefined)[]
    }
    requestEventNamesFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    requestEventNamesSuccess: (
        definitions: EventDefinitionsByName,
        payload?: {
            names: (string | null | undefined)[]
        }
    ) => {
        definitions: EventDefinitionsByName
        payload?: {
            names: (string | null | undefined)[]
        }
    }
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface actionEventHealthLogicMeta {
    __keaTypeGenInternalSelectorTypes: {
        eventHealthIssues: (definitions: EventDefinitionsByName) => Record<string, EventHealthIssue>
    }
}

export type actionEventHealthLogicType = MakeLogicType<
    actionEventHealthLogicValues,
    actionEventHealthLogicActions,
    Record<string, any>,
    actionEventHealthLogicMeta
>

export const actionEventHealthLogic = kea<actionEventHealthLogicType>([
    path(['products', 'actions', 'actionEventHealthLogic']),
    actions({
        requestEventNames: (names: (string | null | undefined)[]) => ({ names }),
    }),
    reducers({
        requestedNames: [
            [] as string[],
            {
                requestEventNames: (state, { names }) => [
                    ...new Set([...state, ...names.filter((name): name is string => !!name)]),
                ],
            },
        ],
    }),
    loaders(({ values }) => ({
        definitions: [
            {} as EventDefinitionsByName,
            {
                requestEventNames: async (_, breakpoint) => {
                    // One page of actions asks for its events row by row, so wait for the burst to settle.
                    await breakpoint(50)
                    const missing = values.requestedNames.filter((name) => !(name in values.definitions))
                    if (!missing.length) {
                        return values.definitions
                    }
                    const response = await api.eventDefinitions.list({ names: missing, limit: missing.length })
                    breakpoint()
                    const resolved: EventDefinitionsByName = { ...values.definitions }
                    for (const name of missing) {
                        resolved[name] = null
                    }
                    for (const definition of response.results) {
                        resolved[definition.name] = definition
                    }
                    return resolved
                },
            },
        ],
    })),
    selectors({
        eventHealthIssues: [
            (s) => [s.definitions],
            (definitions: EventDefinitionsByName): Record<string, EventHealthIssue> => {
                const issues: Record<string, EventHealthIssue> = {}
                for (const [name, definition] of Object.entries(definitions)) {
                    if (!definition) {
                        issues[name] = { status: 'missing' }
                    } else if (definition.last_seen_at && isDefinitionStale(definition)) {
                        issues[name] = { status: 'stale', lastSeenAt: definition.last_seen_at }
                    }
                }
                return issues
            },
        ],
    }),
])
